175	  protected void executeDataTypeConversionOnTypeMismatch(
176	      final IAnalysis analysis, final VerifyMetadataTypeMismatchException e) {
177	    final LoadTsFileDataTypeConverter loadTsFileDataTypeConverter =
178	        new LoadTsFileDataTypeConverter();
179	
180	    final TSStatus status =
181	        isConvertOnTypeMismatch
182	            ? (isTableModelStatement
183	                ? loadTsFileDataTypeConverter
184	                    .convertForTableModel(loadTsFileTableStatement)
185	                    .orElse(null)
186	                : loadTsFileDataTypeConverter
187	                    .convertForTreeModel(loadTsFileTreeStatement)
188	                    .orElse(null))
189	            : null;
190	
191	    if (status == null) {
192	      analysis.setFailStatus(
193	          new TSStatus(TSStatusCode.LOAD_FILE_ERROR.getStatusCode()).setMessage(e.getMessage()));
194	    } else if (!loadTsFileDataTypeConverter.isSuccessful(status)) {
195	      analysis.setFailStatus(status);
196	    }
197	    analysis.setFinishQueryAfterAnalyze(true);
198	    setRealStatement(analysis);
199	  }
